    if parent[i] != i:
        parent[i] = find(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)

    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def is_tree(segment, n, m):
    cells = []
    for i in range(n):
        for j in range(m):
            if segment[i][j] >= l and segment[i][j] <= r:
                cells.append((i, j))

    if len(cells) <= 1:
        return True

    parent = [i for i in range(len(cells))]
    rank = [0] * len(cells)

    for i in range(len(cells)):
        for j in range(i + 1, len(cells)):
            x1, y1 = cells[i]
            x2, y2 = cells[j]
            if abs(x1 - x2) + abs(y1 - y2) == 1:
                union(parent, rank, i, j)

    root = find(parent, 0)
    for i in range(1, len(cells)):
        if find(parent, i) != root:
            return False
    return True

